import {loadBookSummaries,readingFor,editorialHTML} from './book-editorial.js';
import {loadBookIndex,esc,kindLabel,collectPassages,collectMotifs,motifLinks,renderBookFigure} from './book-source.js?v=20261004';
const root=document.querySelector('#book-object-root'),id=new URLSearchParams(location.search).get('id');
try{
 const [index,summaries]=await Promise.all([loadBookIndex(),loadBookSummaries('object')]),object=index.objects.find(item=>item.id===id);
 if(!object)throw new Error('未找到对应的书中对象。请返回纹样探索重新选择。');
 const reading=readingFor(summaries,object,index),passages=collectPassages(index,[object]),motifs=collectMotifs(index,[object]).filter(m=>[m.name,...m.aliases||[]].some(name=>name.length>1&&reading.text.includes(name))).slice(0,8),aliases=[...new Set((object.aliases||[]).filter(name=>name!==object.name))];
 document.title=object.name+' · 书中细读 · 大江大湖间的符号——色彩与文化记忆';document.body.dataset.object=object.id;document.body.dataset.kind=object.kind;
 root.innerHTML=`<section class="bk-object-intro"><p class="bk-eyebrow">BOOK OBJECT <span>/</span> ${esc(kindLabel(object.kind))}</p><h1>${esc(object.name)}</h1>${aliases.length?`<p class="bk-aliases">书中相关名称：${aliases.map(esc).join('、')}</p>`:''}<p class="bk-object-description">来自《${esc(index.source.title)}》的${esc(kindLabel(object.kind))}索引。这里呈现书中记述与配图，相关判断保留其书籍来源。</p></section>
 <section class="bk-object-layout"><div class="bk-object-image" aria-label="书籍索引配图"></div><aside class="bk-object-record"><p class="bk-eyebrow">ABOUT THIS ENTRY</p><h2>书中记录</h2><dl><div><dt>分类</dt><dd>${esc(kindLabel(object.kind))}</dd></div><div><dt>时代</dt><dd>${esc(object.period||'本书此处未明确')}</dd></div><div><dt>地点</dt><dd>${esc(object.place||'本书此处未明确')}</dd></div><div><dt>书中依据</dt><dd>${passages.length} 处记述</dd></div></dl><p class="bk-record-boundary">此页是书籍阅读索引，不作为馆方身份、年代或用途确认。器物类别、文创、文献和遗址建筑分别标示。</p>${object.notes?`<details class="bk-index-note"><summary>查看索引说明</summary><p>${esc(object.notes)}</p></details>`:''}${object.existingId?`<a class="bk-existing-link" href="object.html?id=${encodeURIComponent(object.existingId)}">查看现有器物档案与馆藏来源 ↗</a>`:''}<a class="bk-read-anchor" href="#book-quotes">阅读书中讲解 ↓</a></aside></section>
 <section class="book-source bk-object-reading" id="book-quotes"><header class="bk-section-heading"><div><p class="bk-eyebrow">READING THE BOOK</p><h2>书中讲解</h2></div></header>${editorialHTML(reading,index)}</section>
 <section class="bk-object-motifs"><p class="bk-eyebrow">CONTINUE EXPLORING</p><h2>继续探索</h2>${motifs.length?`<div class="bk-motifs">${motifLinks(motifs)}</div>`:'<p class="bk-empty">回到书中，继续寻找纹样、工艺与色彩的线索。</p>'}<a class="bk-explore" href="book.html">返回纹样探索 ↗</a></section>`;
 const imageHost=root.querySelector('.bk-object-image');if(!renderBookFigure(imageHost,object,index))imageHost.innerHTML='<div class="bk-no-image"><span>以原文为据</span><p>此条索引暂未附可核对的配图。</p><small>下方呈现书中讲解与依据页码。</small></div>';
 document.body.dataset.ready='true';
}catch(error){root.innerHTML=`<section class="bk-page-error"><p class="bk-eyebrow">BOOK OBJECT</p><h1>暂时无法展开这一条</h1><p>${esc(error.message)}</p><a class="bk-explore" href="book.html">返回纹样探索 ↗</a></section>`;document.body.dataset.error='true';console.warn(error)}
